from itertools import permutations
def solve(faces, views):
    # views: list of (top, left, right) seen at a front corner; left->right is clockwise around top viewed from above
    # a cube labelling: opposite pairs; enumerate all labellings as positions
    # positions: U,D,F,B,L,R ; corner view (top,left,right) valid if exists orientation.
    import itertools
    # adjacency cycles around each face in clockwise order when viewed from outside that face
    cyc={'U':['F','L','B','R'],'D':['F','R','B','L'],'F':['U','R','D','L'],'B':['U','L','D','R'],'L':['U','F','D','B'],'R':['U','B','D','F']}
    res=set()
    for p in permutations(faces):
        lab=dict(zip('UDFBLR',p))
        pos={v:k for k,v in lab.items()}
        ok=True
        for t,l,r in views:
            c=cyc[pos[t]]
            if pos[l] not in c or pos[r] not in c: ok=False;break
            # viewed from above with our corner at front: left face then right face appear clockwise? left->right is counter-clockwise from above
            i=c.index(pos[l])
            if c[(i-1)%4]!=pos[r]: ok=False;break
        if ok: res.add(frozenset(frozenset((lab[a],lab[b])) for a,b in ('UD','FB','LR')))
    return res

